import java.util.concurrent.ConcurrentHashMap;

import java.util.concurrent.TimeUnit;

import java.util.logging.Logger;


public class DatabaseHandler {

    private static final Logger logger = Logger.getLogger(DatabaseHandler.class.getName());

    private static final Map<String, Object> queryCache = new ConcurrentHashMap<>();

    private static final long CACHE_TIMEOUT = 60000; // 60 seconds


    public void executeTransaction(String tableName, String columnName, String userInput, String... additionalQueries) {

        String cacheKey = tableName + ":" + columnName + ":" + userInput;

        Object cachedResult = queryCache.get(cacheKey);

        if (cachedResult != null && (System.currentTimeMillis() - cachedResult.getTime()) < CACHE_TIMEOUT) {

            return;

        }


        try {

            Connection conn = Database.getConnection();

            conn.setAutoCommit(false);

            long startTime = System.currentTimeMillis();


            String query = "SELECT * FROM " + tableName + " WHERE " + columnName + " = ?";

            PreparedStatement pstmt = conn.prepareStatement(query);

            pstmt.setString(1, userInput);

            ResultSet rs = pstmt.executeQuery();

            // Process the result set


            for (String additionalQuery : additionalQueries) {

                String additionalQueryKey = tableName + ":" + additionalQuery;

                queryCache.put(additionalQueryKey, rs);

                pstmt = conn.prepareStatement(additionalQuery);

                pstmt.executeUpdate();

            }


            conn.commit();

            long endTime = System.currentTimeMillis();

            logger.info("Transaction executed successfully. Table: " + tableName + ", Query: " + query + ", Execution Time: " + (endTime - startTime) + " ms");

            queryCache.put(cacheKey, rs);

        } catch (SQLException e) {

            conn.rollback();

            logger.severe("Transaction failed. Rollback executed. Error: " + e.getMessage());

        } finally {

            Database.closeConnection(conn);

        }

    }

}

