/**
 * Extracts the SOAP method name from an input stream of a SOAP request, without closing the stream.
 *
 * @param inputStream Source of the SOAP request data @nonnull
 * @param encodingSpec Character encoding specification of the input stream, null uses default system encoding @null
 * @return Extracted SOAP method name or null if the extraction fails @null
 */
private static String extractSoapOperation(InputStream inputStream, String encodingSpec) {
    try {
