private JdbcOptions createDatabaseConnectionOptions(ReadableConfig configSettings) {
    // Retrieve the database URL from the configuration
    final String databaseUrl = configSettings.get(URL);
    Optional<String> customDialectName = configSettings.getOptional(DIALECT_IMPL);
    Optional<JdbcDialect> databaseDialect;

    // Determine if a custom JDBC dialect is specified, otherwise get default dialect based on URL
    if (customDialectName.isPresent()) {
        databaseDialect = JdbcDialects.getCustomDialect(customDialectName.get());
    } else {
        databaseDialect = JdbcDialects.get(databaseUrl);
    }

    // Start configuring JDBC options with retrieved settings
    final JdbcOptions.Builder optionsBuilder = JdbcOptions.builder()
                                                          .setDBUrl(databaseUrl)
                                                          .setTableName(configSettings.get(TABLE_NAME))
                                                          .setDialect(databaseDialect.get())
                                                          .setParallelism(configSettings.getOptional(FactoryUtil.SINK_PARALLELISM).orElse(null))
                                                          .setConnectionCheckTimeoutSeconds((int) configSettings.get(MAX_RETRY_TIMEOUT).getSeconds());

    // Optionally set driver, username, and password if available
    configSettings.getOptional(DRIVER).ifPresent(optionsBuilder::setDriverName);
    configSettings.getOptional(USERNAME).ifPresent(optionsBuilder::setUsername);
    configSettings.getOptional(PASSWORD).ifPresent(optionsBuilder::setPassword);

    // Build and return the configured JDBC options
    return optionsBuilder.build();
}

